INSERT INTO activities (title, description, category, location, country, city, rating, tags, details) VALUES
  ('Ambar', 'Ambar is a modern restaurant chain that blends Balkan tradition with creative design to offer an authentic dining experience. The menu features flavorful Serbian cuisine, including a signature unlimited plates concept and a wide selection of rakias.', 'restaurants', ST_SetSRID(ST_MakePoint(20.448128, 44.819824), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"cuisine":"Balkan / Serbian","price_tier":"$$","hours":"Mon–Fri 11:00–24:00, Sat–Sun 09:00–24:00","popular_dishes":[{"name":"Unlimited Plates Tasting","price":"3200 RSD"},{"name":"Rakia Flight","price":"1200 RSD"}]}'::jsonb),
  ('Pečat Restoran', 'Pečat Restoran is a modern Serbian establishment that offers traditional flavors prepared in a refined, contemporary way. The menu features signature dishes such as veal cooked under the bell, premium steaks, and tableside preparations.', 'restaurants', ST_SetSRID(ST_MakePoint(20.467035, 44.794228), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"cuisine":"Modern Serbian","price_tier":"$$$","hours":"Daily 11:30–23:00","popular_dishes":[{"name":"Veal Under the Bell","price":"2400 RSD"},{"name":"Premium Steak","price":"2900 RSD"}],"action_url":"http://www.pecatrestoran.rs/"}'::jsonb),
  ('Kafana Pavle Korcagin', 'This traditional Serbian tavern features a socialist Yugoslavia theme and offers a wide selection of home-cooked meals and local drinks. The venue is known for having live music every night of the week and a smart casual atmosphere.', 'restaurants', ST_SetSRID(ST_MakePoint(20.481752, 44.803886), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY[]::TEXT[], '{"cuisine":"Serbian tavern (kafana)","price_tier":"$$","hours":"Mon–Sat 08:00–01:00, Sun 10:00–22:00","popular_dishes":[{"name":"Home-Cooked Daily Special","price":"900 RSD"},{"name":"Mixed Grill Platter","price":"1400 RSD"}],"action_url":"http://kafanapavlekorcagin.rs/kafana-pavle-korcagin-beograd"}'::jsonb),
  ('MAMA''S Bistro', 'A top-rated family-run bistro serving International and European cuisine, specializing in handmade pasta, grilled dishes, and homemade bread.', 'restaurants', ST_SetSRID(ST_MakePoint(20.453955, 44.816788), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"cuisine":"International / European","price_tier":"$$","hours":"Daily 09:00–23:00","popular_dishes":[{"name":"Handmade Pasta","price":"1200 RSD"},{"name":"Grilled Plate","price":"1600 RSD"}],"action_url":"http://mamasbistro.rs/"}'::jsonb),
  ('Mezestoran Dvorište', 'This Mediterranean and European restaurant serves traditional Greek cuisine including gyros, tzatziki, and chickpea fritters in a joyful atmosphere. It features an informal setting with a refreshingly shady alfresco patio area in a central courtyard.', 'restaurants', ST_SetSRID(ST_MakePoint(20.469887, 44.812645), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"cuisine":"Greek / Mediterranean","price_tier":"$$","hours":"Tue–Sun 09:00–23:00 (Mon closed)","popular_dishes":[{"name":"Gyros Plate","price":"1100 RSD"},{"name":"Meze Selection","price":"1500 RSD"}],"action_url":"http://restorandvoriste.rs/"}'::jsonb),
  ('Zavicaj Restaurant', 'This traditional ethno restaurant serves authentic Balkan cuisine in a rustic setting decorated with Serbian folk art and pottery.', 'restaurants', ST_SetSRID(ST_MakePoint(20.458416, 44.80938), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"cuisine":"Balkan / ethno","price_tier":"$$","hours":"Daily 09:00–23:00","popular_dishes":[{"name":"Ćevapi Platter","price":"950 RSD"},{"name":"Stuffed Peppers","price":"850 RSD"}]}'::jsonb),
  ('Curry Souls', 'Curry Souls is a modern Sri Lankan curry house serving authentic South-Asian street food in the city center of Belgrade. It is known for its flavorful dishes and vibrant atmosphere where flavor meets the heart.', 'restaurants', ST_SetSRID(ST_MakePoint(20.456873, 44.81624), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"cuisine":"Sri Lankan / South Asian","price_tier":"$$","hours":"Daily 11:00–23:00","popular_dishes":[{"name":"Chicken Curry Bowl","price":"1050 RSD"},{"name":"Kottu Roti","price":"1150 RSD"}],"action_url":"http://www.currysouls.com/"}'::jsonb),
  ('Gradska', 'Gradska is an authentic Serbian restaurant specializing in national cuisine from the Toplica district of South Serbia. It is located in a green park oasis in the heart of old Belgrade at Dorcol.', 'restaurants', ST_SetSRID(ST_MakePoint(20.46457, 44.825157), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"cuisine":"Serbian (Toplica region)","price_tier":"$$","hours":"Tue–Sun 10:00–22:30 (Mon closed)","popular_dishes":[{"name":"Toplica Roast","price":"1500 RSD"},{"name":"Homemade Sausage","price":"1100 RSD"}],"action_url":"http://www.gradska.rs/"}'::jsonb),
  ('To Je To', 'A traditional European barbecue restaurant specializing in Sarajevo-style cuisine and authentic grilled meats like cevapcici. This family-run establishment is highly ranked for its casual atmosphere and traditional Balkan dishes.', 'restaurants', ST_SetSRID(ST_MakePoint(20.466476, 44.816853), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"cuisine":"Balkan barbecue (Sarajevo-style)","price_tier":"$","hours":"Mon–Sat 09:00–20:00, Sun 11:00–20:00","popular_dishes":[{"name":"Sarajevo Ćevapi","price":"700 RSD"},{"name":"Somun \u0026 Kajmak","price":"300 RSD"}],"action_url":"http://sarajevski-cevapi.com/"}'::jsonb),
  ('Tri Sesira', 'A traditional Serbian restaurant specializing in European and barbecue cuisine. It is known for its bohemian atmosphere and live traditional music.', 'restaurants', ST_SetSRID(ST_MakePoint(20.464775, 44.818123), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"cuisine":"Traditional Serbian","price_tier":"$$","hours":"Daily 11:00–02:00","popular_dishes":[{"name":"Skadarlija Grill","price":"1600 RSD"},{"name":"Roast Lamb","price":"1800 RSD"}],"action_url":"http://trisesira.rs/"}'::jsonb),
  ('Jazz Cafe', 'A bar and cafe in Belgrade offering vegetarian-friendly, vegan, and gluten-free options for breakfast, lunch, dinner, and brunch. The venue features a jazz-themed interior with trumpet chandeliers and outdoor seating in a pedestrian area.', 'cafes', ST_SetSRID(ST_MakePoint(20.458433, 44.815544), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"known_for_brew":"All-day espresso \u0026 brunch coffee","hours":"Daily, breakfast to late"}'::jsonb),
  ('Koffein', 'Unusual coffee shop just around the corner located in a pedestrian zone of the city center. Very close to Knez Mihailova with excellent coffee selection.', 'cafes', ST_SetSRID(ST_MakePoint(20.454784, 44.817856), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"known_for_brew":"Excellent city-centre espresso selection","hours":"Mon–Sat 08:00–23:00, Sun 09:00–23:00"}'::jsonb),
  ('Coffee Dream Dorćol', 'International coffee and tea spot serving breakfast, lunch, and dinner. Features include artistic coffee, cakes, frappes, ice cream, fresh squeezed juices, outdoor seating, and free wifi.', 'cafes', ST_SetSRID(ST_MakePoint(20.461437, 44.82158), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"known_for_brew":"Artistic coffee, frappes \u0026 fresh juices","wifi_quality":"Free wifi, outdoor seating","hours":"Mon–Thu 08:00–24:00, Fri–Sun 08:00–01:00","on_the_bar":[{"name":"Frappe","price":"320 RSD"},{"name":"Cake Slice","price":"420 RSD"}]}'::jsonb),
  ('Cafe Moskva', 'This historic Belgrade landmark is one of the oldest and best-known pastry shops in the region, famous for its signature Moskva Šnit cake and live piano performances in an elegant, traditional atmosphere.', 'cafes', ST_SetSRID(ST_MakePoint(20.460611, 44.81296), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"known_for_brew":"Historic pastry house — Moskva Šnit \u0026 coffee","hours":"Daily 07:00–24:00","on_the_bar":[{"name":"Moskva Šnit","price":"550 RSD"},{"name":"Espresso","price":"250 RSD"}]}'::jsonb),
  ('NEGRO caffe', 'This unique downtown cafe serves as a quiet oasis for private conversations and features live music, cocktails, and a selection of desserts.', 'cafes', ST_SetSRID(ST_MakePoint(20.460619, 44.813923), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"known_for_brew":"Quiet downtown café with desserts \u0026 cocktails","hours":"Open 24 hours"}'::jsonb),
  ('Aviator Coffee Explorer', 'This central Belgrade cafe features a modern industrial interior and specializes in a wide variety of coffee origins, including Colombian and Ethiopian beans.', 'cafes', ST_SetSRID(ST_MakePoint(20.461464, 44.812428), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"known_for_brew":"Single-origin beans (Colombian, Ethiopian)","hours":"Daily"}'::jsonb),
  ('uzitak coffee selection and delights', 'This cozy cafe features a selection of finest single origin espresso and homemade products in a professional, friendly atmosphere. It is known for roasting its coffee on the spot and serving fresh juices in the heart of the city.', 'cafes', ST_SetSRID(ST_MakePoint(20.466585, 44.81534), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY[]::TEXT[], '{"known_for_brew":"Single-origin espresso, roasted on the spot","hours":"Mon–Fri 07:00–21:00, Sat–Sun 09:00–17:00"}'::jsonb),
  ('Coffee Room Serbia', 'This cafe focuses on creating memorable moments for guests by offering a wide variety of high-quality sweets, macarons, and artisanal pastries.', 'cafes', ST_SetSRID(ST_MakePoint(20.455154, 44.81658), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"known_for_brew":"Coffee with macarons \u0026 artisanal pastries","hours":"Daily 09:00–23:00","on_the_bar":[{"name":"Macaron","price":"180 RSD"},{"name":"Cappuccino","price":"280 RSD"}]}'::jsonb),
  ('Kafe Supa', 'Located in the heart of Belgrade, this cafe offers a warm atmosphere with an unusual blend of vintage and industrial interior.', 'cafes', ST_SetSRID(ST_MakePoint(20.454618, 44.814114), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY[]::TEXT[], '{"known_for_brew":"Vintage-industrial café, all-day coffee","hours":"Open 24 hours"}'::jsonb),
  ('Cafe&Factory', 'This specialty cafe is known for roasting its own beans and offering a wide variety of international coffees in a central pedestrian location. It features a popular outdoor seating area and is highly rated for its professional service and fresh coffee quality.', 'cafes', ST_SetSRID(ST_MakePoint(20.460758, 44.785217), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"known_for_brew":"In-house roastery, international coffees","hours":"Daily 08:00–24:00"}'::jsonb),
  ('The Black Turtle Pub', 'Nice little, cozy place, hidden in a basement with good seasonal beers.', 'bars', ST_SetSRID(ST_MakePoint(20.450886, 44.817585), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"vibe":"Cozy basement pub with seasonal beers","opens_time":"09:00","signature_pours":["Seasonal craft beers","Local lagers"],"action_url":"http://www.theblackturtle.com/"}'::jsonb),
  ('Harry''s Bar', 'Unique western style bar with cool crowd, trendy music, and relaxing atmosphere.', 'bars', ST_SetSRID(ST_MakePoint(20.4785, 44.8065), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"vibe":"Western-style bar, trendy music","signature_pours":["Cocktails","Whiskey"]}'::jsonb),
  ('Harat''s Pub Belgrade', 'Authentic Irish pub with cozy wooden interior, impressive selection of beers and whiskeys, and friendly staff.', 'bars', ST_SetSRID(ST_MakePoint(20.45483, 44.819283), 4326)::geography, 'Serbia', 'Belgrade', 4.2, ARRAY[]::TEXT[], '{"vibe":"Authentic Irish pub, wooden interior","opens_time":"09:00","signature_pours":["Draught beers","Whiskey selection"],"action_url":"http://www.harats.com/"}'::jsonb),
  ('Krafter Bar', 'Cosy laid back place at Dorćol serving variety of craft beer with good vibe.', 'bars', ST_SetSRID(ST_MakePoint(20.4601, 44.822186), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY[]::TEXT[], '{"vibe":"Laid-back Dorćol craft-beer spot","signature_pours":["Rotating craft beers"],"action_url":"http://www.facebook.com/Krafter-1700535863498303/"}'::jsonb),
  ('Corner Pub', 'Nice venue with friendly atmosphere, relaxing familiar pub feeling and classic rock music.', 'bars', ST_SetSRID(ST_MakePoint(20.457958, 44.8096), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"vibe":"Friendly pub, classic rock","opens_time":"08:30","signature_pours":["Draught beer","Pub classics"],"action_url":"http://pivnicabeograd.com/"}'::jsonb),
  ('Spasicev Pub Belgrade', 'Fun place to experience local life with good selection of draft beers, food, live music and sports on TV.', 'bars', ST_SetSRID(ST_MakePoint(20.454847, 44.81853), 4326)::geography, 'Serbia', 'Belgrade', 4.2, ARRAY[]::TEXT[], '{"vibe":"Local pub with food, live music \u0026 sports","signature_pours":["Draft beers"],"action_url":"http://www.facebook.com/spasicevpub/"}'::jsonb),
  ('Gvint', 'Craft lager taproom in Dorćol Platz offering house-brewed lagers including classic, dark, IPA, red, and Italian pilsner since 2018.', 'bars', ST_SetSRID(ST_MakePoint(20.4625, 44.8215), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"vibe":"Craft lager taproom in Dorćol Platz","opens_time":"12:00","signature_pours":["House Classic Lager","Dark Lager","IPA","Italian Pilsner"],"action_url":"http://www.gvint.rs/"}'::jsonb),
  ('Docker Brewery And Beer Garden', 'New and trendy brewery with large choice of beers and IPAs in an industrial area setting.', 'bars', ST_SetSRID(ST_MakePoint(20.471647, 44.82337), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"vibe":"Trendy industrial brewery \u0026 beer garden","signature_pours":["House beers","IPAs"],"action_url":"http://dockers.rs/"}'::jsonb),
  ('Dogma Brewery', 'Small batch craft brewery dedicated to making special hoppy ales with a great tap room atmosphere.', 'bars', ST_SetSRID(ST_MakePoint(20.465, 44.8125), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"vibe":"Small-batch craft brewery taproom","opens_time":"12:00","signature_pours":["Hoppy ales","Seasonal specials"],"action_url":"http://dogmabrewery.com/"}'::jsonb),
  ('Koi Bar • Sushi And Cocktail', 'Vibrant and trendy spot in Skadarlija district offering exquisite sushi and expertly crafted cocktails for an upscale experience.', 'restaurants', ST_SetSRID(ST_MakePoint(20.463495, 44.81676), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"cuisine":"Japanese / sushi","price_tier":"$$$","hours":"Daily 16:00–24:00","popular_dishes":[{"name":"Signature Sushi Set","price":"2600 RSD"},{"name":"Sashimi Selection","price":"2200 RSD"}],"action_url":"https://www.instagram.com/koibarbelgrade/"}'::jsonb),
  ('Hype', 'First luxury and high class club in Belgrade featuring the latest lighting and sound system, playing House, tech house, funky, disco, R''n''B and hits from 80''s, 90''s.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4473, 44.8083), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"dress_code":"Elegant / smart casual","opens_time":"23:00","action_url":"http://www.hypebelgrade.com/","venue_type":"Club"}'::jsonb),
  ('The Bank Club', 'First Premium RnB club in this part of Europe with high level service, located at the most exclusive place in Belgrade at Beton Hala.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4475, 44.8177), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"dress_code":"Smart elegant","opens_time":"23:30","action_url":"https://www.instagram.com/the_bank_belgrade/","venue_type":"RnB club"}'::jsonb),
  ('Gatsby', 'Club-type facility at the mouth of Sava and Danube rivers with extremely pleasant ambiance and exceptional equipment, operating with live bands and DJs.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4564, 44.8233), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY[]::TEXT[], '{"dress_code":"Smart casual","opens_time":"21:45","action_url":"http://www.gatsby.rs/","venue_type":"Live music club"}'::jsonb),
  ('Club 20/44', 'Floating club vessel on the Sava river with an undergroundish but friendly vibe, offering an authentic Belgrade party experience.', 'nightlife', ST_SetSRID(ST_MakePoint(20.445, 44.815), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"dress_code":"Casual","opens_time":"22:00","action_url":"http://20-44.com/","venue_type":"Floating club"}'::jsonb),
  ('Freestyler Belgrade Nightclub', 'Legendary floating club on the river operating for over 20 years, welcoming top international DJs and a fun, stylish crowd from all over the world.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4055, 44.8518), 4326)::geography, 'Serbia', 'Belgrade', 3.6, ARRAY[]::TEXT[], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Splav TAG Belgrade Nightclub', 'Riverbank nightclub with state-of-the-art sound systems, mesmerizing light shows, dancers and performers, featuring spectacular performances and dynamic dance floor.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4319, 44.8189), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"entry_price":"1000 RSD","dress_code":"Smart casual","opens_time":"23:00","open_tonight":true,"lineup":[{"time":"23:30","act":"Resident DJ","stage":"Main Floor"},{"time":"01:00","act":"Guest DJ","stage":"Terrace"}]}'::jsonb),
  ('Leto Belgrade', 'Summer club at the spot where Sava River meets the Danube with stunning view of Kalemegdan Fortress, gathering urban lovers of quality electronic beats.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4564, 44.8233), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"dress_code":"Casual","opens_time":"22:00","action_url":"http://letobelgrade.com/","venue_type":"Summer club"}'::jsonb),
  ('KULT', 'Underground club with capacity of 300 people featuring flawless Funktion-One sound system, playing house, deep house, progressive house, tech house, minimal, and techno. Age limit 23+.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4567, 44.817), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"dress_code":"Casual, 23+","opens_time":"21:00","action_url":"https://www.instagram.com/club.kult/","venue_type":"Underground club"}'::jsonb),
  ('Money Club', 'First Summer RnB Club in Belgrade with great summer vibe, beautiful interior, and crazy cocktails. Entry is free, age limit 23+, dress code elegant or smart casual.', 'nightlife', ST_SetSRID(ST_MakePoint(20.4319, 44.8189), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"dress_code":"Elegant / smart casual, 23+","opens_time":"23:55","action_url":"https://www.facebook.com/moneybelgrade/","venue_type":"RnB club"}'::jsonb),
  ('Drugstore Club Beograd', 'Underground techno club in a former meat factory space, perfect for those who like dark techno music and partying in a more shady environment.', 'nightlife', ST_SetSRID(ST_MakePoint(20.465, 44.82), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"dress_code":"Casual","opens_time":"23:59","action_url":"https://www.facebook.com/drugstore.beograd","venue_type":"Techno club"}'::jsonb),
  ('Ada Ciganlija', 'A beloved river island turned peninsula featuring pristine nature, biking trails, rowing, running facilities, and beach areas along the Sava River.', 'nature', ST_SetSRID(ST_MakePoint(20.4, 44.7833), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"time_to_spend":"Half a day","best_time":"Late spring to summer","cost":"Free","good_to_know":["Beach \u0026 swimming in summer","Bike and rowing rentals","Gets crowded on weekends"]}'::jsonb),
  ('Kalemegdan Park and Belgrade Fortress', 'Historic fortress park perched at the confluence of the Sava and Danube rivers, featuring walking paths, monuments, and panoramic views from 125 meters above sea level.', 'culture', ST_SetSRID(ST_MakePoint(20.451, 44.824421), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"venue_type":"Fortress \u0026 heritage park","ticket_price":"Free entry","hours":"Open daily","now_showing":{"title":"Fortress Walk","description":"Ramparts, monuments and panoramic views over the Sava–Danube confluence."}}'::jsonb),
  ('Košutnjak Hill', 'A sprawling green forest oasis with dense tree canopy, winding walking trails, and abundant picnic areas, popular for relaxation and family gatherings.', 'nature', ST_SetSRID(ST_MakePoint(20.435, 44.76667), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"time_to_spend":"2–3 hours","best_time":"Morning","cost":"Free","good_to_know":["Shaded forest trails","Plenty of picnic spots","Good for families"]}'::jsonb),
  ('Mountain Avala', 'A hiking destination featuring a well-prepared 1700-meter route to the summit, with an iconic TV tower offering panoramic views and a coffee shop.', 'nature', ST_SetSRID(ST_MakePoint(20.51602, 44.68902), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"time_to_spend":"Half a day","best_time":"Clear days for the views","cost":"Free (TV tower ticket extra)","good_to_know":["1700 m trail to the summit","Avala Tower viewpoint","Coffee shop at the top"]}'::jsonb),
  ('Topčider Park', 'One of Belgrade''s oldest parks featuring diverse trees, fresh air, historic sites including Peter and Paul church, and a 200-year-old London plane tree.', 'nature', ST_SetSRID(ST_MakePoint(20.4595, 44.7736), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"time_to_spend":"1–2 hours","best_time":"Spring \u0026 autumn","cost":"Free","good_to_know":["200-year-old London plane tree","Peter and Paul church on site","Fresh air and old trees"]}'::jsonb),
  ('Great War Island', 'A wild river island at the confluence of Sava and Danube, featuring Lido Beach on its northern tip and accessible via pontoon bridge in summer.', 'nature', ST_SetSRID(ST_MakePoint(20.43, 44.85), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"time_to_spend":"Half a day","best_time":"Summer","cost":"Free","good_to_know":["Lido Beach on the northern tip","Reached by summer pontoon bridge","Wild, protected nature"]}'::jsonb),
  ('Tašmajdan Park', 'A large urban park in the city center with many walking paths, monuments dedicated to important Serbian historical figures, and beautiful green spaces.', 'nature', ST_SetSRID(ST_MakePoint(20.47076, 44.81008), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Zemunski Park', 'A historic seven-hectare park in the heart of Zemun''s old core, established in 1880, featuring sports facilities, schools, and flanked by Orthodox and Catholic churches.', 'nature', ST_SetSRID(ST_MakePoint(20.403, 44.843), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"time_to_spend":"1 hour","best_time":"Spring \u0026 autumn","cost":"Free","good_to_know":["Established in 1880","Sports facilities on site","In the old core of Zemun"]}'::jsonb),
  ('Jevremovac Botanical Garden', 'A small botanical garden in central Belgrade featuring a renovated greenhouse, diverse plant collections, and old trees providing a peaceful retreat.', 'nature', ST_SetSRID(ST_MakePoint(20.47322, 44.81581), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"time_to_spend":"1–2 hours","best_time":"Spring","cost":"Low entry fee","good_to_know":["Renovated historic greenhouse","Diverse plant collections","Peaceful central retreat"]}'::jsonb),
  ('Belgrade Zoo', 'One of the oldest zoos in Southeastern Europe, located in Kalemegdan Park, home to around 800 animals representing 210 species including white wolves and hippos.', 'kids', ST_SetSRID(ST_MakePoint(20.45333, 44.82583), 4326)::geography, 'Serbia', 'Belgrade', 3.7, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["~800 animals, 210 species","Inside Kalemegdan Park","Open 09:00–17:00 daily","Picnic areas nearby"]}'::jsonb),
  ('XL Fitness Factory', 'XL Fitness factory is an exclusive fitness center located in Belgrade with specialized facilities where professional trainers help you reach every fitness goal.', 'wellness', ST_SetSRID(ST_MakePoint(20.48011, 44.8168481), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"treatments":[{"item":"Personal Training Session","duration":"60 min"},{"item":"Open Gym Access","duration":"Day pass"}],"external_booking_note":"Professional trainers on site; walk-ins welcome during opening hours.","action_url":"https://teretanaxl.rs/","venue_type":"Gym / fitness centre"}'::jsonb),
  ('Sky Experience', '950m2 high-end gym with the newest Technogym equipment located at the confluence of Danube and Sava rivers in Belgrade, ranked top 10 in the world for its location and innovation.', 'wellness', ST_SetSRID(ST_MakePoint(20.4547, 44.8238), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"treatments":[{"item":"Open Gym Access","duration":"Day pass"},{"item":"Technogym Equipment Session","duration":"60 min"}],"external_booking_note":"High-end 950m2 gym at the river confluence; day passes available at reception.","action_url":"https://www.skyexperience.rs/","venue_type":"Gym / fitness centre"}'::jsonb),
  ('Extreme gym', 'The best gym in town with excellent staff, exercise machines, and trainers located in the center near all good hotels.', 'wellness', ST_SetSRID(ST_MakePoint(20.4686, 44.817), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"treatments":[{"item":"Open Gym Access","duration":"Day pass"},{"item":"Personal Training Session","duration":"60 min"}],"external_booking_note":"City-centre gym near major hotels; trainers available on request.","action_url":"http://www.x3mgym.com/","venue_type":"Gym / fitness centre"}'::jsonb),
  ('Swimming Pool Tasmajdan', 'Large pool with clean water where many water polo and swimming clubs have training and matches.', 'sport', ST_SetSRID(ST_MakePoint(20.4761, 44.8083), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"difficulty":2,"effort_level":"Moderate","duration":"1-2 hours","gear":"Equipment available on site","what_to_bring":["Water bottle","Sportswear"]}'::jsonb),
  ('Kosutnjak Swimming Pool', 'Every day you can have a good time at the pools with necessary facilities for all ages.', 'sport', ST_SetSRID(ST_MakePoint(20.435, 44.7667), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"difficulty":2,"effort_level":"Moderate","duration":"1-2 hours","gear":"Equipment available on site","what_to_bring":["Water bottle","Sportswear"]}'::jsonb),
  ('Golf Club Belgrade', 'Golf course located on Ada Ciganlija with nine golf holes totaling 4860m (2x9 holes), 68 PAR, just four kilometers from the city center.', 'sport', ST_SetSRID(ST_MakePoint(20.4084157, 44.7928733), 4326)::geography, 'Serbia', 'Belgrade', 3.6, ARRAY[]::TEXT[], '{"effort_level":"Easy–moderate","duration":"2–4 hours","gear":"Clubs available for rent","what_to_bring":["Flat shoes","Sun protection"],"action_url":"http://www.golfclub.co.rs/","discipline":"Golf"}'::jsonb),
  ('Novak Tennis Center', 'Tennis center in the heart of Belgrade with 14 courts (11 premium clay, 3 hard surfaces) surrounded by Kalemegdan and located at the confluence of Sava and Danube Rivers.', 'sport', ST_SetSRID(ST_MakePoint(20.4545, 44.8235), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"effort_level":"Moderate","duration":"1–2 hours","gear":"Rackets and balls available","what_to_bring":["Sportswear","Court shoes"],"action_url":"https://www.novaktenniscenter.com/","discipline":"Tennis"}'::jsonb),
  ('Sport Centre 11. April', 'Sports centre with basketball court, table tennis hall, bowling alley, shooting gallery, weightlifting gym, indoor pool and open-air pools including Olympic swimming pool and tennis courts.', 'sport', ST_SetSRID(ST_MakePoint(20.4052, 44.8086), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"difficulty":2,"effort_level":"Moderate","duration":"1-2 hours","gear":"Equipment available on site","what_to_bring":["Water bottle","Sportswear"]}'::jsonb),
  ('Planet Gym & Fitness', 'Ultra-modern unisex fitness center with the best amenities and training equipment, open 24 hours with a wide range of classes and exercising programs.', 'wellness', ST_SetSRID(ST_MakePoint(20.5096145, 44.8177458), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"treatments":[{"item":"Open Gym Access","duration":"Day pass"},{"item":"Group Fitness Class","duration":"45 min"}],"external_booking_note":"Open 24 hours; classes and equipment for all levels.","action_url":"https://planetgym.rs/en/","venue_type":"Gym / fitness centre"}'::jsonb),
  ('Climbing Gym Gekon', 'Old-school climbing gym with welcoming community and top-notch coaching, featuring 18m indoor wall for rope climbing.', 'sport', ST_SetSRID(ST_MakePoint(20.465, 44.8214), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"effort_level":"Moderate–hard","duration":"1.5–2 hours","gear":"Harness \u0026 shoes for rent","what_to_bring":["Comfortable clothes","Chalk (optional)"],"discipline":"Climbing"}'::jsonb),
  ('Museum of Illusions', 'A fascinating world of illusions featuring over 70 interactive exhibits that are both educational and entertaining for families, offering visual trickery and perspective-based puzzles.', 'entertainment', ST_SetSRID(ST_MakePoint(20.4569, 44.8169), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"genre":"Interactive attraction","neighborhood":"City centre","upcoming_shows":[{"date":"Daily","title":"70+ Illusion Exhibits","time_or_price":"09:00–21:00"}],"action_url":"http://muzejiluzija.rs/"}'::jsonb),
  ('Nikola Tesla Museum', 'A science museum dedicated to the life and legacy of inventor Nikola Tesla with guided tours that include demonstrations of his experiments, appealing to families and science enthusiasts.', 'culture', ST_SetSRID(ST_MakePoint(20.4707, 44.8051), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"venue_type":"Science museum","ticket_price":"Paid entry","hours":"Tue–Sun 10:00–20:00, Mon 10:00–18:00","now_showing":{"title":"Tesla Experiments","description":"Guided tour with live demonstrations of Tesla''s inventions."},"action_url":"https://tesla-museum.org"}'::jsonb),
  ('Public Aquarium and Tropicarium Belgrade', 'A gathering place for children and families to see aquatic and tropical ecosystems from around the world, featuring biotopes of local and international rivers, seas, and lakes along with reptiles, mammals and insects.', 'kids', ST_SetSRID(ST_MakePoint(20.4695, 44.8142), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Aquatic \u0026 tropical biotopes","Reptiles, mammals \u0026 insects","Weekday 12:00–20:00, weekend 09:00–16:00"]}'::jsonb),
  ('Dino Park Jura Avantura', 'A dinosaur-themed park featuring life-size dinosaur models and interactive exhibits, perfect for young children who enjoy prehistoric creatures. Located within the historic Belgrade Fortress.', 'kids', ST_SetSRID(ST_MakePoint(20.45, 44.8236), 4326)::geography, 'Serbia', 'Belgrade', 3.3, ARRAY[]::TEXT[], '{"age_range":"Young children","facilities":["Life-size dinosaur models","Interactive exhibits","Inside Belgrade Fortress","Open 10:15–20:00"]}'::jsonb),
  ('Playroom Mia', 'A combined children''s playroom and modern cafeteria featuring a climbing wall, slides, trampolines, and toys for kids, while offering a space for parents to relax with coffee and local food.', 'kids', ST_SetSRID(ST_MakePoint(20.4083, 44.8534), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Selfie Museum Expose', 'An interactive exhibition with 27 unique attractions across 500 square meters featuring themed rooms perfect for creative photos, designed for families and those who enjoy fun, memorable experiences.', 'entertainment', ST_SetSRID(ST_MakePoint(20.4648, 44.8073), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"genre":"Interactive photo attraction","neighborhood":"City centre","upcoming_shows":[{"date":"Daily","title":"27 Themed Photo Rooms","time_or_price":"10:00–22:00"}],"action_url":"http://selfiemuseum.rs/"}'::jsonb),
  ('Museum of Science and Technology', 'A museum showcasing technical history with three levels of exhibitions including industrial equipment, vintage cameras, early computing relics, and a children''s department with interactive activities and workshops adapted for younger visitors.', 'culture', ST_SetSRID(ST_MakePoint(20.4678, 44.8311), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"venue_type":"Science \u0026 technology museum","ticket_price":"Paid entry","now_showing":{"title":"Industry \u0026 Invention","description":"Industrial equipment, vintage cameras, early computing, plus a children''s workshop wing."},"action_url":"http://www.muzejnt.rs"}'::jsonb),
  ('Skakaonica AVA PARK', 'A 4,800 square meter trampoline park offering over 30 unique attractions including climbing walls, free jump arena, ninja warrior course, ropes course, and specialized toddler areas with soft play zones.', 'kids', ST_SetSRID(ST_MakePoint(20.3845, 44.7893), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Igraj.rs Kids Playground - Ada Mall', 'A 350 square meter rooftop kids center with glass architecture featuring age-specific zones for children 3-12, including soft play areas, ball pits, space-themed 3D maze, zip lines, trampolines, and educational workshops.', 'kids', ST_SetSRID(ST_MakePoint(20.414, 44.7869), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"age_range":"All ages","facilities":["Baby changing rooms","Playground","Picnic area"]}'::jsonb),
  ('Belgrade Fortress', 'This historic fortress is located at the highest point of the city overlooking the confluence of the Sava and Danube Rivers. Today, the fortress grounds serve as a spacious city park featuring historic gates, ramparts, and the Serbian Military Museum.', 'nature', ST_SetSRID(ST_MakePoint(20.4497647, 44.8235022), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"time_to_spend":"2-3 hours","best_time":"Early morning","cost":"Free","good_to_know":["Wear comfortable shoes","Gets busy on weekends"]}'::jsonb),
  ('Church of Saint Sava', 'One of the largest Orthodox temples in the world, this landmark features a magnificent interior covered in golden mosaics and is inspired by the Hagia Sophia in Istanbul.', 'culture', ST_SetSRID(ST_MakePoint(20.469116, 44.7981), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"venue_type":"Orthodox temple","ticket_price":"Free entry","hours":"08:00–20:00","now_showing":{"title":"Golden Mosaic Dome","description":"One of the world''s largest Orthodox churches, inspired by Hagia Sophia."}}'::jsonb),
  ('Republic Square', 'A central square in Belgrade surrounded by the National Museum and National Theatre. It serves as a popular meeting point and hub for shopping, dining, and people watching.', 'culture', ST_SetSRID(ST_MakePoint(20.460111, 44.816444), 4326)::geography, 'Serbia', 'Belgrade', 4.5, ARRAY[]::TEXT[], '{"venue_type":"Historic city square","ticket_price":"Free","hours":"Open 24 hours","now_showing":{"title":"The Heart of Belgrade","description":"Meeting point framed by the National Museum and National Theatre."}}'::jsonb),
  ('St. Mark''s Church', 'A grand Serbian-Byzantine style church built between 1931 and 1940, located within the Tašmajdan Park. It is recognized as a cultural monument and known for its striking architecture.', 'culture', ST_SetSRID(ST_MakePoint(20.4685, 44.8101), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"venue_type":"Serbian-Byzantine church","ticket_price":"Free entry","now_showing":{"title":"Tašmajdan Landmark","description":"Monumental 1931–1940 church, a protected cultural monument."}}'::jsonb),
  ('National Museum Belgrade', 'The oldest and largest museum in Serbia, featuring extensive archaeological collections from ancient times and a significant art collection with works by masters like Picasso, Monet, and Renoir.', 'culture', ST_SetSRID(ST_MakePoint(20.4594, 44.8167), 4326)::geography, 'Serbia', 'Belgrade', 4.1, ARRAY[]::TEXT[], '{"venue_type":"National museum","ticket_price":"Paid entry","hours":"Wed/Fri/Sun 10:00–18:00, Thu/Sat 12:00–20:00","now_showing":{"title":"From Antiquity to the Masters","description":"Archaeology plus paintings by Picasso, Monet and Renoir."},"action_url":"http://en.narodnimuzej.rs/"}'::jsonb),
  ('Nebojša Tower', 'A late 14th-century historical monument and well-preserved tower located in the lower part of the Belgrade Fortress. It originally served as a defensive structure and currently houses a multimedia museum.', 'culture', ST_SetSRID(ST_MakePoint(20.451, 44.8215), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"venue_type":"Heritage site","ticket_price":"Free entry","hours":"09:00-19:00","now_showing":{"title":"Permanent Collection","description":"Self-guided visit of the main halls."}}'::jsonb),
  ('Residence of Princess Ljubica', 'This museum showcases 19th-century living for an affluent family in Belgrade, featuring an evolution of interior styles from Ottoman to Central European. The residence was built around 1830 for Princess Ljubica Obrenovic.', 'culture', ST_SetSRID(ST_MakePoint(20.45227, 44.81712), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"venue_type":"Historic residence museum","ticket_price":"Paid entry","now_showing":{"title":"19th-Century Belgrade Living","description":"Interiors from Ottoman to Central European style, built c.1830."},"action_url":"http://www.mgb.org.rs/visit/details/25"}'::jsonb),
  ('Bajrakli Mosque', 'This 16th-century Ottoman building is the only remaining mosque in Belgrade. It features a classic square design with a single dome and minaret and remains an active place of worship.', 'culture', ST_SetSRID(ST_MakePoint(20.4575, 44.8222), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"venue_type":"Ottoman mosque","ticket_price":"Free entry","now_showing":{"title":"Belgrade''s Last Mosque","description":"16th-century single-dome Ottoman mosque, still an active place of worship."}}'::jsonb),
  ('Ružica Church', 'A historic Serbian Orthodox church located within the Belgrade Fortress, famous for its unique chandeliers made from military weapons and its beautiful interior frescoes.', 'culture', ST_SetSRID(ST_MakePoint(20.449, 44.8235), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"venue_type":"Orthodox church","ticket_price":"Free entry","now_showing":{"title":"Chandeliers of Arms","description":"Fortress church famous for chandeliers made from military weapons."},"action_url":"http://www.serbia.travel/culture/religious-buildings/orthodox-churches---new-age/Crkva-Rodjenja-Presvete-Bogorodice-Ruzica-Beograd.a-204.669.html"}'::jsonb),
  ('Saint Petka''s Chapel', 'This small Orthodox sanctuary is located within the Belgrade Fortress and is renowned for its vibrant interior mosaics and peaceful atmosphere. It was built in 1937 on the site of a miraculous spring.', 'culture', ST_SetSRID(ST_MakePoint(20.4495, 44.8238), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"venue_type":"Orthodox chapel","ticket_price":"Free entry","now_showing":{"title":"Mosaics \u0026 Holy Spring","description":"1937 chapel over a miraculous spring, with vibrant interior mosaics."},"action_url":"http://www.serbia.travel/culture/religious-buildings/orthodox-churches-xx-century/chapel-of-saint-petkabelgrade/"}'::jsonb),
  ('Museum of Contemporary Art Belgrade', 'A contemporary art museum with multiple floors of exhibition space featuring Yugoslav, Serbian and international art of the 20th and 21st century.', 'art', ST_SetSRID(ST_MakePoint(20.4424765, 44.8195844), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"venue_type":"Contemporary art museum","ticket_price":"Paid entry","hours":"Wed–Mon 11:00–19:00 (Thu/Sat to 20:00), Tue closed","current_exhibition":{"title":"20th–21st Century Collection","description":"Yugoslav, Serbian and international modern and contemporary art."},"action_url":"https://msub.org.rs"}'::jsonb),
  ('Zepter Museum', 'A private museum of contemporary art founded in 2010 featuring paintings, sculptures, and installations by recent Serbian artists.', 'art', ST_SetSRID(ST_MakePoint(20.4558415, 44.8186363), 4326)::geography, 'Serbia', 'Belgrade', 4.4, ARRAY[]::TEXT[], '{"venue_type":"Contemporary art museum","ticket_price":"Paid entry","hours":"Wed–Sun (Mon/Tue closed)","current_exhibition":{"title":"Recent Serbian Art","description":"Paintings, sculptures and installations, collection founded 2010."},"action_url":"https://zeptermuzej.rs"}'::jsonb),
  ('Art for All', 'Art gallery and concept store showcasing young artists'' work including paint, illustration, street art, sculpture, design, photography and fashion.', 'art', ST_SetSRID(ST_MakePoint(20.452341, 44.8176081), 4326)::geography, 'Serbia', 'Belgrade', 4.8, ARRAY[]::TEXT[], '{"venue_type":"Gallery \u0026 concept store","ticket_price":"Free entry","hours":"Mon–Fri 11:00–20:00, Sat 11:00–15:00","current_exhibition":{"title":"Young Artists Showcase","description":"Illustration, street art, sculpture, design, photography and fashion."},"action_url":"https://artforallgallery.com"}'::jsonb),
  ('Green Door - Gallery & Art Gift Shop', 'A charming art gallery offering handmade pieces and hosting regular exhibitions supporting local artists in a warm and welcoming space.', 'art', ST_SetSRID(ST_MakePoint(20.4564744, 44.8210607), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"venue_type":"Gallery \u0026 art gift shop","ticket_price":"Free entry","hours":"Mon–Fri 14:00–20:00, Sat 11:00–15:00","current_exhibition":{"title":"Local Makers","description":"Handmade pieces and rotating exhibitions by local artists."}}'::jsonb),
  ('Eugster Belgrade', 'A contemporary art gallery focusing on artists from the Balkans region, showing art in calm surroundings designed by TEN Zürich.', 'art', ST_SetSRID(ST_MakePoint(20.4837975, 44.8253154), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"venue_type":"Gallery","ticket_price":"500 RSD","hours":"10:00-18:00","current_exhibition":{"title":"Contemporary Local Artists","description":"Rotating group show."}}'::jsonb),
  ('Belgrade City Museum', 'A museum located in a 19th-century former military building hosting temporary exhibitions including modern and abstract art.', 'culture', ST_SetSRID(ST_MakePoint(20.4612075, 44.8041879), 4326)::geography, 'Serbia', 'Belgrade', 4.7, ARRAY[]::TEXT[], '{"venue_type":"City museum","ticket_price":"Paid entry","now_showing":{"title":"Rotating Exhibitions","description":"Temporary shows including modern and abstract art in a 19th-century building."},"action_url":"http://www.mgb.org.rs"}'::jsonb),
  ('Museum of African Art', 'The first museum dedicated to African cultures in southeastern Europe, featuring masks, musical instruments, and cultural artifacts from West Africa.', 'art', ST_SetSRID(ST_MakePoint(20.435042, 44.7890765), 4326)::geography, 'Serbia', 'Belgrade', 4.6, ARRAY[]::TEXT[], '{"venue_type":"Art \u0026 culture museum","ticket_price":"Paid entry","current_exhibition":{"title":"West African Collection","description":"Masks, musical instruments and artifacts — the region''s first African art museum."},"action_url":"https://mau.rs"}'::jsonb),
  ('Cultural Centre of Belgrade - Fine Arts Gallery', 'Located in the Press Centre Building, it includes the Fine Arts Gallery, Gallery Artget, and Gallery Podroom hosting cultural exhibitions.', 'art', ST_SetSRID(ST_MakePoint(20.4597675, 44.81543), 4326)::geography, 'Serbia', 'Belgrade', 0, ARRAY[]::TEXT[], '{"venue_type":"Fine arts galleries","ticket_price":"Free entry","current_exhibition":{"title":"Artget \u0026 Podroom","description":"Rotating exhibitions across the Fine Arts, Artget and Podroom galleries."},"action_url":"https://www.kcb.org.rs"}'::jsonb),
  ('O3ONE Art Space', 'An independent art gallery showcasing contemporary visual arts with a focus on fostering dialogue between art, technology, and science.', 'art', ST_SetSRID(ST_MakePoint(20.4669, 44.823), 4326)::geography, 'Serbia', 'Belgrade', 4.3, ARRAY[]::TEXT[], '{"venue_type":"Independent gallery","ticket_price":"Free entry","hours":"Wed 12:00–20:00","current_exhibition":{"title":"Art × Technology × Science","description":"Contemporary visual art fostering cross-disciplinary dialogue."},"action_url":"http://www.o3one.rs"}'::jsonb),
  ('Excellence Massage Belgrade', 'Certified masseurs and therapists offer an extensive selection of over 60 types of massages, catering to both men and women of all age groups.', 'wellness', ST_SetSRID(ST_MakePoint(20.4633, 44.8176), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"treatments":[{"item":"Relaxing Massage","duration":"60 min"},{"item":"Deep Tissue Massage","duration":"60 min"}],"external_booking_note":"Over 60 massage types; book ahead via the website.","action_url":"http://excellencemassagebelgrade.rs/","venue_type":"Massage"}'::jsonb),
  ('Palata Oh My Goodness Massage Belgrade', 'Second largest massage center in Southeast Europe offering highly professional massages for relaxation of body and soul.', 'wellness', ST_SetSRID(ST_MakePoint(20.4534, 44.8174), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"treatments":[{"item":"Full-Body Massage","duration":"60 min"},{"item":"Couples Massage","duration":"60 min"}],"external_booking_note":"One of SE Europe''s largest massage centres; reservations recommended.","action_url":"https://oh-my-goodness-massage.rs/","venue_type":"Massage"}'::jsonb),
  ('Bali Detox', 'Center for psychophysical rest, relaxation and body detoxication offering various types of massages in the heart of Belgrade.', 'wellness', ST_SetSRID(ST_MakePoint(20.463, 44.819), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"treatments":[{"item":"Balinese Massage","duration":"60 min"},{"item":"Body Detox Treatment","duration":"75 min"}],"external_booking_note":"Book via the website; Sun hours are shorter.","action_url":"http://www.balidetox.com/en/","venue_type":"Spa"}'::jsonb),
  ('Bali SPA Massage Centar', 'Center for psychophysical rest and relaxation offering various types of massages including relax, anti-cellulite, detox, volcanic rocks, and yoga massage.', 'wellness', ST_SetSRID(ST_MakePoint(20.4632, 44.8192), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"treatments":[{"item":"Sauna \u0026 Pool Access","duration":"Full day","price":"3500 RSD"},{"item":"Relaxing Massage","duration":"60 min","price":"4500 RSD"}],"external_booking_note":"Book treatments at least 24 hours in advance."}'::jsonb),
  ('Varijanta Massage Center', 'Massage center in the heart of the city with a team of professionals offering all kinds of body care massages to raise overall health.', 'wellness', ST_SetSRID(ST_MakePoint(20.4534, 44.8174), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"treatments":[{"item":"Body Care Massage","duration":"60 min"},{"item":"Sports Massage","duration":"45 min"}],"external_booking_note":"Open 10:00–23:00 daily; call to reserve.","venue_type":"Massage"}'::jsonb),
  ('Caesar Spa Club', 'The first private luxury Spa Club in Belgrade where you can enjoy exclusive experiences in total privacy.', 'wellness', ST_SetSRID(ST_MakePoint(20.48, 44.808), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"treatments":[{"item":"Private Spa Session","duration":"Varies"},{"item":"Signature Massage","duration":"60 min"}],"external_booking_note":"Private luxury spa; advance booking required.","action_url":"http://caesarspa.rs/","venue_type":"Spa"}'::jsonb),
  ('Reset Room Spa', 'Upscale massage place and head spa offering deeply relaxing and luxurious premium treatments.', 'wellness', ST_SetSRID(ST_MakePoint(20.47, 44.82), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"treatments":[{"item":"Head Spa","duration":"45 min"},{"item":"Premium Relax Massage","duration":"60 min"}],"external_booking_note":"Upscale treatments; reserve in advance.","venue_type":"Spa"}'::jsonb),
  ('Siam Spa - Traditional Thai Massage', 'Real, sophisticated, prestigious Thai massage experience with 20 certified professional therapists from Thailand on 2 locations in Belgrade.', 'wellness', ST_SetSRID(ST_MakePoint(20.4633, 44.8176), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"treatments":[{"item":"Traditional Thai Massage","duration":"60 min"},{"item":"Aromatherapy Massage","duration":"60 min"}],"external_booking_note":"Certified Thai therapists; two locations, book ahead.","action_url":"http://siamspa.rs/","venue_type":"Thai massage"}'::jsonb),
  ('My Relax Corner', 'Modern equipped studio for professional massages located in the heart of Belgrade, representing an oasis of peace and relaxation.', 'wellness', ST_SetSRID(ST_MakePoint(20.47, 44.825), 4326)::geography, 'Serbia', 'Belgrade', 4.9, ARRAY[]::TEXT[], '{"treatments":[{"item":"Relaxation Massage","duration":"60 min"}],"external_booking_note":"Tue–Sun 10:00–20:00 (Mon closed); by appointment.","action_url":"http://www.relaxkutak.rs/","venue_type":"Massage"}'::jsonb),
  ('Sa-Wan Thai Massage', 'Offers Traditional Thai massage, aromatherapy Thai massage, couples massage, head & neck massage and foot massage with experienced professionals from Thailand.', 'wellness', ST_SetSRID(ST_MakePoint(20.4633, 44.8176), 4326)::geography, 'Serbia', 'Belgrade', 5, ARRAY[]::TEXT[], '{"treatments":[{"item":"Traditional Thai Massage","duration":"60 min"},{"item":"Foot Massage","duration":"45 min"}],"external_booking_note":"Experienced Thai therapists; open 10:00–21:00 daily.","venue_type":"Thai massage"}'::jsonb),
  ('UŠĆE Shopping Center', 'World-class shopping center with a large selection of world-renowned stores and Serbian manufacturers in a beautiful building.', 'shopping', ST_SetSRID(ST_MakePoint(20.4365, 44.8155), 4326)::geography, 'Serbia', 'Belgrade', 4, ARRAY[]::TEXT[], '{"venue_type":"Shopping mall","hours":"Daily 10:00–22:00","what_youll_find":["International \u0026 Serbian brands","Food court","Cinema"]}'::jsonb),
